def test_cleaning_staff_invitation_insert_update_at_the_loaded_version_and_conflicts() -> None:
    """Optimistic locking: what the repository did not load is inserted (version 1); what it loaded
    is updated only at the loaded version. No row back (a lost race) is a ConcurrencyConflict.
    """
    aggregate = CleaningStaffInvitation(
        id=UUID("00000000-0000-0000-0000-000000000001"),
        email=EmailAddress(value="staff@example.com"),
        status=InvitationStatus.PENDING,
        created_at=datetime.fromisoformat("2026-01-01T10:00:00+00:00"),
        expires_at=datetime.fromisoformat("2026-01-08T10:00:00+00:00"),
    )
    connection = _ScriptedConnection([{"version": 1}], [{"version": 2}], [])
    repository: CleaningStaffInvitationRepository = PostgresCleaningStaffInvitationRepository(
        connection
    )
    repository.save(aggregate)
    repository.save(aggregate)
    with pytest.raises(ConcurrencyConflict):
        repository.save(aggregate)
    assert connection.queries == [
        CLEANING_STAFF_INVITATION_TABLE.insert,
        CLEANING_STAFF_INVITATION_TABLE.update,
        CLEANING_STAFF_INVITATION_TABLE.update,
    ]
    assert [params.get("p7") for params in connection.params] == [None, 1, 2]
    loaded = _ScriptedConnection(
        [{**_database_row(cleaning_staff_invitation_to_row(aggregate)), "version": 7}],
        [],
    )
    other = PostgresCleaningStaffInvitationRepository(loaded)
    found = other.get(aggregate.id)
    assert found is not None
    assert found.same_state_as(aggregate)
    with pytest.raises(ConcurrencyConflict):
        other.save(aggregate)
    assert loaded.params[1]["p7"] == 7


def test_cursor_codec_signature_fingerprint_rotation_and_expiry() -> None:
    """Cursors are signed: another secret, another fingerprint or an expired token is rejected;
    rotation accepts the old secret.
    """
    old = HmacCursorCodec(["old-secret-0123456789-0123456789-0123"])
    token = old.encode(["a", 1, True], "fingerprint")
    rotated = HmacCursorCodec(
        ["new-secret-0123456789-0123456789-0123", "old-secret-0123456789-0123456789-0123"]
    )
    assert rotated.decode(token, "fingerprint") == ("a", 1, True)
    with pytest.raises(InvalidCursor) as signature:
        HmacCursorCodec(["new-secret-0123456789-0123456789-0123"]).decode(token, "fingerprint")
    assert signature.value.details["reason"] == "signature"
    with pytest.raises(InvalidCursor) as mismatch:
        rotated.decode(token, "other")
    assert mismatch.value.details["reason"] == "mismatch"
    clock = [1000.0]
    expiring = HmacCursorCodec(
        ["new-secret-0123456789-0123456789-0123"],
        ttl_seconds=60,
        now=lambda: clock[0],
    )
    short = expiring.encode(["x"], "fingerprint")
    assert expiring.decode(short, "fingerprint") == ("x",)
    clock[0] += 60
    with pytest.raises(InvalidCursor) as expired:
        expiring.decode(short, "fingerprint")
    assert expired.value.details["reason"] == "expired"
    with pytest.raises(ValueError, match="32 characters"):
        HmacCursorCodec(["short"])


def test_trigram_similarity_follows_pg_trgm() -> None:
    """The in-memory trigram similarity is pg_trgm's (expected values from PostgreSQL's show_trgm /
    similarity).
    """
    assert sorted(trigrams("staff@example.com")) == [
        "  c",
        "  e",
        "  s",
        " co",
        " ex",
        " st",
        "aff",
        "amp",
        "com",
        "exa",
        "ff ",
        "le ",
        "mpl",
        "om ",
        "ple",
        "sta",
        "taf",
        "xam",
    ]
    assert sorted(trigrams("ab-cd")) == ["  a", "  c", " ab", " cd", "ab ", "cd "]
    assert similarity("staff@example.com", "staf") == 0.21052631735801697
    assert similarity("abc", "abd") == 0.3333333432674408
    assert similarity("", "abc") == 0.0
